pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: send 2 ether to c via Put with a unlockTime far in the future
        vm.deal(address(0x1234), 2 ether);
        vm.prank(address(0x1234));
        c.Put{value: 2 ether}(block.timestamp + 1000);

        // Try Collect(1 ether) before the unlockTime - should revert in reference due to block.timestamp <= unlockTime
        vm.prank(address(0x1234));
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }

        // In reference, the call reverts (Collect condition fails) -> ok is false, LogFile not updated
        // In modified, the revert condition is removed -> ok is true, LogFile not updated either (no AddMessage call)
        // Note: The reference does NOT send the 'Collect' message because the condition fails.
        // The divergence is that the modified version does not call LogFile.AddMessage, but the reference also does not.
        // Actually we need a scenario where the reference logs and the modified does not.
        // Let's redo: use a scenario where the collect succeeds in reference (after unlock) and modified does not have the AddMessage call.

        // Reset: deploy fresh
        setUp();
        vm.warp(0);
        vm.deal(address(0x1234), 2 ether);
        vm.prank(address(0x1234));
        c.Put{value: 2 ether}(0);  // unlockTime = block.timestamp (0), so immediately collectable

        // Now perform Collect(1 ether) - should succeed in both versions? The modified version has the same logic except missing LogFile.AddMessage in Put.
        // But Put already missed the log. We need the Collect to trigger AddMessage in reference but not in modified.
        // In reference, Collect calls LogFile.AddMessage; in modified, it does not (since the only change is in Put, not Collect).
        // Actually the modified version has exactly one changed statement: line "LogFile.AddMessage(msg.sender,msg.value,"Put");" removed from Put.
        // So Collect code is identical in both.
        // Therefore we need a scenario where the divergent behavior arises from the missing log in Put.
        // Let's check: after Put, the reference logs, the modified does not. So we can assert that after a Put, the last message (if we had a getter) would be from reference but not from modified.
        // But the Log contract's History is not directly exposed via C. However, the Log is deployed at address(this) in setUp? Actually c is constructed with address(this) as log, meaning the test contract itself is the Log.
        // So we can query the Log's History array via the test contract's own functions? No, Log is a separate contract instance. But the test contract can call c.LogFile() to get the address of the Log contract.
        // Then we can call Log(addr).History(0) etc.
        // Let's use that.
        address logAddr = c.LogFile();
        Log logContract = Log(logAddr);
        // After Put(0) from 0x1234 with 2 ether, reference should have a History message, modified should not.
        // Since History is dynamic, if length is 0 the getter will revert or return 0? We can check length via vm.
        // Instead, we can assert that the LastMsg sender in Log is the caller in reference, but in modified it's zero.
        // But LastMsg is private? No, it's not public, so no getter.
        // Alternative: call History.length via eth_call? Not directly from Solidity unless we have a getter for length. History is public, so there is an auto-generated getter: History(uint) returns (address,string,uint,uint). Also a length getter? In Solidity, public arrays have a length getter automatically. So we can call logContract.History(0) to get the first element, but we need to know if it exists.
        // Simpler: assert that after Put, the Log's History length is greater than 0 in reference, and 0 in modified (since modified doesn't call AddMessage).
        // But we can't get length directly from function call? Actually we can: logContract.History() returns length? No, for arrays, the getter is uint256 length()? In Solidity, for a public array, there is an auto-generated getter that takes an index. The length is not directly accessible as a function. We can use vm.getNonce? Not allowed.
        // We can use vm.getRecordedLogs? Not allowed.
        // Alternative: we can call AddMessage ourselves? No.
        // We can deploy a new Log contract and check via events? But cheatcodes limited.
        // We can indirectly assert via a try/catch on History getter: if History(0) reverts (out of bounds), then length = 0.
        // Let's do that: try logContract.History(0) { ok = true; } catch { ok = false; }
        // In reference, it should succeed; in modified, it should revert.
    }
}

