pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Alice puts 2 ether with unlock time 100
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Put{value: 2 ether}(100);
        // warp past unlock time
        vm.warp(200);
        // Alice collects 1 ether
        vm.prank(alice);
        c.Collect(1 ether);
        // Now check Log's History length via c's LogFile getter then call History length
        // c.LogFile() returns address of Log contract
        // We can call History.length on that address
        (bool ok, bytes memory data) = address(c.LogFile()).staticcall(abi.encodeWithSignature("History(uint256)", 0));
        // We'll just assert on the length; we need to read length via getter
        // Actually Log has public History array, so we can call c.LogFile() to get address then .History
        // Better: use vm to call the log's HistoryLength
        // But easier: the Log contract is deployed by C constructor with address(this) as log, so we know its address
        // but we can get it via c.LogFile()
        address logAddr = c.LogFile();
        // Read History length via public getter array length
        // public arrays auto-generate length() getter
        (bool success, bytes memory result) = logAddr.staticcall(abi.encodeWithSignature("length()"));
        require(success);
        uint256 length = abi.decode(result, (uint256));
        assertEq(length, 2);
    }
}

