pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: give caller 2 ether
        vm.deal(address(this), 2 ether);
        // Put 1 ether with unlock time 0 (so block.timestamp > unlockTime)
        c.Put{value: 1 ether}(0);
        // Collect 1 ether (satisfies balance>=MinSum, balance>=_am, block.timestamp > unlockTime)
        c.Collect(1 ether);
        // Assert that the Log contract's History length is 1 (reference adds the message, buggy version does not)
        // c.LogFile() returns the Log contract address; we need to interact with it via its public getter
        // But Log is a separate contract deployed by C; we can call its History getter via address
        Log logFile = Log(c.LogFile());
        assertEq(logFile.HistoryLength(), 1);
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    mapping(uint => uint) private dummy;

    function HistoryLength() public view returns (uint) {
        return History.length;
    }

    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

