pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user puts 1 ether with unlock time = block.timestamp - 1 (past)
        // Then user collects 0.5 ether
        vm.deal(address(0x123), 2 ether);
        vm.prank(address(0x123));
        c.Put{value: 1 ether}(block.timestamp - 1);

        vm.warp(block.timestamp + 2); // warp past the unlock time (which was set to block.timestamp - 1 => now block.timestamp > that)

        // Now collect 0.5 ether
        vm.prank(address(0x123));
        bool ok;
        try c.Collect(0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);

        // After collect, user's balance should be 0.5 ether
        (uint unlockTime, uint balance) = c.Acc(address(0x123));
        assertEq(balance, 0.5 ether);
    }
}

