import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up two users
        address alice = address(0x1111);
        address bob = address(0x2222);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);

        // Alice deposits 1 ether with unlock time = current timestamp
        vm.prank(alice);
        c.Put{value: 1 ether}(block.timestamp);

        // Bob deposits 0 ether (triggers fallback -> Put(0))
        vm.prank(bob);
        (bool successBob,) = address(c).call{value: 0 ether}("");
        assertTrue(successBob); // ensure call succeeded

        // Warp past the unlock time
        vm.warp(block.timestamp + 1 days);

        // Alice tries to collect 1 ether
        bool successAlice;
        try c.Collect(1 ether) { successAlice = true; } catch { successAlice = false; }

        // Assert that Alice's collect succeeded (reference holds, buggy version reverts due to overflow)
        assertTrue(successAlice);
    }
}

