// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: user puts 2 ether with unlock time in the past, then collects 2 ether
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.startPrank(user);
        vm.warp(1000);
        // Put 2 ether with unlockTime 500 (already passed)
        c.Put{value: 2 ether}(500);
        // After put, MinSum is 1 ether, balance is 2 ether, unlockTime is 1000, so collect is possible before warp?
        // Actually unlockTime becomes max(500, block.timestamp) = 1000, need to warp past 1000
        vm.warp(1001);
        // Collect 2 ether
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", 2 ether));
        assertTrue(ok);
