import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user deposits 2 ether, unlock time set to 100 (already past), then tries to collect 1 ether.
        vm.deal(address(0x1234), 5 ether);
        vm.prank(address(0x1234));
        c.Put{value: 2 ether}(100);
        vm.warp(200); // block.timestamp > unlock time (100)
        vm.prank(address(0x1234));
        // The Collect call may revert if LogFile.AddMessage reverts (modified version)
        bool collectOk;
        try c.Collect(1 ether) {
            collectOk = true;
        } catch {
            collectOk = false;
        }
        // In the reference, Collect succeeds, so address(this) received Log history (including Collect message)
        // The Log contract's History array length will be 2 (one for Put, one for Collect).
        // In the modified version, LogFile address is address(0) -> revert in AddMessage -> collectOk == false -> history length remains 1.
        (bool callOk, bytes memory returnData) = address(this).staticcall(abi.encodeWithSignature("History(uint256)",1));
        // If History[1] exists, length >= 2; callOk will be true if the second message was stored.
        assertTrue(collectOk && callOk);
    }
}

